grid=[[9]*26 for _ in range(11)]
pts=[(4,10),(4,22),(5,22),(6,11),(6,13),(6,14),(6,15),(6,16),(6,17),(6,20),(6,21),(8,10),(8,19),(8,22)]
for r,c in pts:grid[r][c]=3
# fill between all markers in each shared row and col
for r in range(11):
 cs=[c for rr,c in pts if rr==r]
 if len(cs)>=2:
  for c in range(min(cs),max(cs)+1):
   if grid[r][c]==9:grid[r][c]=2
for c in range(26):
 rs=[r for r,cc in pts if cc==c]
 if len(rs)>=2:
  for r in range(min(rs),max(rs)+1):
   if grid[r][c]==9:grid[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in grid))
